using System.Text.Json;
namespace KaraokeFilmMaker.Application.Ai;
public interface IAiToolExecutor
{
    JsonElement Definitions { get; }
    Task<object> ExecuteAsync(string name, JsonElement arguments, CancellationToken token);
}
public sealed class AiToolBridge(Func<string, JsonElement, CancellationToken, Task<object>> execute) : IAiToolExecutor
{
    private readonly System.Collections.Concurrent.ConcurrentDictionary<string, byte> _installationRequests = new(StringComparer.Ordinal);
    public JsonElement Definitions => Catalog;
    public static JsonElement Catalog { get; } = JsonDocument.Parse("""
[{"name": "get_alignment_install_guide", "description": "读取本地打轴插件安装与使用 skill；首次安装或自动打轴前调用。", "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}}, {"name": "get_alignment_plugins", "description": "查询两种本地打轴插件安装状态、CPU/GPU配置检查和当前歌曲默认模型。", "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}}, {"name": "open_alignment_plugins", "description": "打开图形化本地打轴插件管理页面。", "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}}, {"name": "install_alignment_plugin", "description": "用户 Approve 后下载并安装本地打轴插件，执行真实推理自检。先检查配置。无 API Key，不能声称下载即安装成功。", "parameters": {"type": "object", "properties": {"pluginId": {"type": "string", "enum": ["nextfire", "qwen"]}, "device": {"type": "string", "enum": ["cpu", "gpu"]}}, "required": ["pluginId", "device"], "additionalProperties": false}}, {"name": "align_lyrics", "description": "使用本地插件分段自动打轴；日语默认 NextFire，其他语言默认 Qwen。保留发音校正和人工打点，用户批准后应用并保存，可撤销。", "parameters": {"type": "object", "properties": {"pluginId": {"type": "string", "enum": ["auto", "nextfire", "qwen"]}, "correctReadings": {"type": "boolean", "description": "默认 true；用户明确采用已人工校对读音时可 false。"}}, "required": [], "additionalProperties": false}}, {"name": "open_asr_configuration", "description": "打开 ASR 配置窗口，由用户填写。不得索取、读取或传递密钥；不安装或部署模型。", "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}}, {"name": "correct_japanese_readings", "description": "使用已配置 Qwen ASR 识别当前歌曲并逐句校正日语歌词读音。用户批准后执行、自动保存，可撤销；成功结果直接应用，无需逐句确认；失败在打轴页标记，已有人工内容和打点保留。不承诺全部正确，不自动打轴。缺配置会打开配置窗口。", "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}}, {"name": "get_project_context", "description": "读取当前项目摘要、歌曲、画幅、页面和选择；不返回本地路径。", "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}}, {"name": "get_lyrics", "description": "读取歌词、读音、角色与打点。行号从1开始，每次最多50行。", "parameters": {"type": "object", "properties": {"startLine": {"type": "integer", "minimum": 1}, "count": {"type": "integer", "minimum": 1, "maximum": 50}}, "required": [], "additionalProperties": false}}, {"name": "get_subtitle_style", "description": "读取标准字幕样式或指定项目角色样式。", "parameters": {"type": "object", "properties": {"roleId": {"type": "string", "description": "项目角色 GUID，省略为标准样式"}}, "required": [], "additionalProperties": false}}, {"name": "list_style_resources", "description": "查询字体、字幕预设、保存样式与项目角色。", "parameters": {"type": "object", "properties": {"fontQuery": {"type": "string", "description": "字体名称过滤，可省略"}}, "required": [], "additionalProperties": false}}, {"name": "update_subtitle_style", "description": "部分更新字幕样式，可撤销。不修改歌词或打点。先读取样式再计算相对改动。", "parameters": {"type": "object", "properties": {"roleId": {"type": "string", "description": "项目角色 GUID，省略为标准样式"}, "patch": {"type": "object", "properties": {"primaryFontSize": {"type": "number", "description": "primaryFontSize"}, "annotationFontSize": {"type": "number", "description": "annotationFontSize"}, "outlineWidth": {"type": "number", "description": "outlineWidth"}, "shadowOffset": {"type": "number", "description": "shadowOffset"}, "lineGap": {"type": "number", "description": "lineGap"}, "marginRatio": {"type": "number", "description": "marginRatio"}, "fontFamily": {"type": "string", "description": "字体名称或 #AARRGGBB 颜色"}, "inactiveColor": {"type": "string", "description": "字体名称或 #AARRGGBB 颜色"}, "activeColor": {"type": "string", "description": "字体名称或 #AARRGGBB 颜色"}, "outlineColor": {"type": "string", "description": "字体名称或 #AARRGGBB 颜色"}, "activeOutlineColor": {"type": "string", "description": "字体名称或 #AARRGGBB 颜色"}, "showRomanization": {"type": "boolean"}}, "additionalProperties": false}}, "required": ["patch"], "additionalProperties": false}}, {"name": "update_song_title", "description": "部分修改曲名设置，可撤销。", "parameters": {"type": "object", "properties": {"patch": {"type": "object", "properties": {"fontSize": {"type": "number", "description": "fontSize"}, "outlineWidth": {"type": "number", "description": "outlineWidth"}, "shadowOffset": {"type": "number", "description": "shadowOffset"}, "marginRatio": {"type": "number", "description": "marginRatio"}, "text": {"type": "string", "description": "text"}, "fontFamily": {"type": "string", "description": "fontFamily"}, "color": {"type": "string", "description": "color"}, "outlineColor": {"type": "string", "description": "outlineColor"}, "enabled": {"type": "boolean"}, "position": {"type": "string", "enum": ["TopLeft", "TopRight"]}}, "additionalProperties": false}}, "required": ["patch"], "additionalProperties": false}}, {"name": "set_visualization", "description": "开关现有可视化或切换模式，不支持烟花。", "parameters": {"type": "object", "properties": {"enabled": {"type": "boolean"}, "mode": {"type": "string", "enum": ["Classic", "BottomDense", "CenterWhite", "RotatingRing"]}}, "required": [], "additionalProperties": false}}, {"name": "seek_preview", "description": "暂停并跳转预览，seconds与line二选一。行号从1开始。", "parameters": {"type": "object", "properties": {"seconds": {"type": "number", "description": "原歌曲时间，秒"}, "line": {"type": "integer", "minimum": 1}}, "required": [], "additionalProperties": false}}, {"name": "search_music", "description": "搜索并依次校验音频，在聊天内显示首个可播放歌曲卡片。返回 selectionId 可用于 import_music；不会自动播放或导入。", "parameters": {"type": "object", "properties": {"query": {"type": "string", "description": "歌名或歌手"}, "source": {"type": "string", "enum": ["netease", "tencent", "qishui"]}}, "required": ["query"], "additionalProperties": false}}, {"name": "open_music_search", "description": "搜索并依次校验音频，在聊天内显示首个可播放歌曲卡片。返回 selectionId 可用于 import_music；不会自动播放或导入。", "parameters": {"type": "object", "properties": {"query": {"type": "string", "description": "可选预填搜索关键词"}}, "required": ["query"], "additionalProperties": false}}, {"name": "create_workspace", "description": "创建并保存工作区。用户选择空目录并 Approve 后执行；当前项目也会先保存。不接受任意文件路径。", "parameters": {"type": "object", "properties": {"title": {"type": "string"}}, "required": ["title"], "additionalProperties": false}}, {"name": "import_music", "description": "将聊天歌曲卡片导入为当前项目歌曲；用户 Approve 后执行并自动保存。仅支持已校验完整音频。", "parameters": {"type": "object", "properties": {"selectionId": {"type": "string"}}, "required": ["selectionId"], "additionalProperties": false}}, {"name": "get_user_memory", "description": "读取用户明确保存的长期偏好。", "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}}, {"name": "remember_user_preference", "description": "仅在用户明确要求记住偏好时调用；经用户批准保存跨项目长期记忆，不保存密钥。", "parameters": {"type": "object", "properties": {"text": {"type": "string"}}, "required": ["text"], "additionalProperties": false}}, {"name": "forget_user_preference", "description": "用户批准后删除指定长期记忆，ID来自get_user_memory。", "parameters": {"type": "object", "properties": {"id": {"type": "string"}}, "required": ["id"], "additionalProperties": false}}, {"name": "import_lyrics", "description": "导入用户提供的 TXT/LRC 歌词文本，替换全部歌词和打点；先展示内容，经批准保存，可撤销。不可凭空编造歌词。", "parameters": {"type": "object", "properties": {"text": {"type": "string", "maxLength": 50000}, "format": {"type": "string", "enum": ["txt", "lrc"]}}, "required": ["text", "format"], "additionalProperties": false}}, {"name": "edit_lyrics", "description": "按 get_lyrics 返回的行 ID 修改、删除、插入或移动歌词，或修正原文片段读音。expectedText 必须匹配原文。读音 rangeStart 从0开始，rangeLength 为原文字符数；修改会重建受影响单元并清除其失效打点，经批准后保存可撤销。", "parameters": {"type": "object", "properties": {"action": {"type": "string", "enum": ["replace", "reading", "insert_before", "insert_after", "delete", "move"]}, "lineId": {"type": "string"}, "expectedText": {"type": "string"}, "text": {"type": "string"}, "reading": {"type": "string"}, "rangeStart": {"type": "integer", "minimum": 0}, "rangeLength": {"type": "integer", "minimum": 1}, "destinationLine": {"type": "integer", "minimum": 1}}, "required": ["action", "lineId", "expectedText"], "additionalProperties": false}}]
""").RootElement.Clone();
    public Task<object> ExecuteAsync(string name, JsonElement arguments, CancellationToken token)
    {
        var definition = Catalog.EnumerateArray().FirstOrDefault(x => x.GetProperty("name").GetString() == name);
        if (definition.ValueKind == JsonValueKind.Undefined || arguments.ValueKind != JsonValueKind.Object)
            throw new InvalidOperationException("工具或参数无效。");
        Validate(arguments, definition.GetProperty("parameters"));
        token.ThrowIfCancellationRequested();
        // A bridge is created once per user turn. Device changes are still the same plugin attempt.
        if (name == "install_alignment_plugin" && !_installationRequests.TryAdd(arguments.GetProperty("pluginId").GetString()!, 0))
            return Task.FromResult<object>(new { installed=false, blocked=true, reason="installation_already_requested_this_turn", requiresUserReply=true,
                message="本轮已经申请过安装此插件，不再展示第二张批准卡。请报告首次结果，等待用户明确要求重试或切换 CPU/GPU；下载失败不代表 GPU 不可用。" });
        return execute(name, arguments, token);
    }
    private static void Validate(JsonElement value, JsonElement schema)
    {
        string? type=schema.GetProperty("type").GetString();
        bool valid=type switch { "object"=>value.ValueKind==JsonValueKind.Object,"string"=>value.ValueKind==JsonValueKind.String,
            "boolean"=>value.ValueKind is JsonValueKind.True or JsonValueKind.False,"integer"=>value.ValueKind==JsonValueKind.Number&&value.TryGetInt32(out _),"number"=>value.ValueKind==JsonValueKind.Number && value.TryGetDouble(out double n)&&double.IsFinite(n),_=>false };
        if(!valid)throw new InvalidOperationException("工具参数类型无效。");
        if(schema.TryGetProperty("enum",out var choices)&&!choices.EnumerateArray().Any(x=>x.GetRawText()==value.GetRawText()))throw new InvalidOperationException("工具参数不在允许范围。");
        if(type=="string"&&value.GetString()!.Length>(schema.TryGetProperty("maxLength", out var maxLength) ? maxLength.GetInt32() : 2000))throw new InvalidOperationException("参数过长。");
        if(type is "number" or "integer")
        {if(schema.TryGetProperty("minimum",out var min)&&value.GetDouble()<min.GetDouble()||schema.TryGetProperty("maximum",out var max)&&value.GetDouble()>max.GetDouble())throw new InvalidOperationException("数值超出范围。");}
        if(type!="object")return;
        var properties=schema.GetProperty("properties");
        foreach(var p in value.EnumerateObject())
        {if(!properties.TryGetProperty(p.Name,out var ps))throw new InvalidOperationException("存在不支持的参数。");Validate(p.Value,ps);}
        if(schema.TryGetProperty("required",out var required))foreach(var p in required.EnumerateArray())if(!value.TryGetProperty(p.GetString()!,out _))throw new InvalidOperationException("缺少必要参数。");
    }
}
